97	+/// Read the data of one part of this crate.
98	+///
99	+/// Returns `None` with no log for a part that is not `ProviderData` or that
100	+/// has the key of another provider. Returns `None` with a debug log for a part
101	+/// with this key that does not parse, or that holds a block that is not valid.
102	+/// The log never holds the content of the part.
103	+pub(crate) fn from_part(part: &ContentPart) -> Option<(AnthropicData, Option<&str>)> {
104	+    let ContentPart::ProviderData {
105	+        provider,
106	+        call_id,
107	+        data,
108	+    } = part
109	+    else {
110	+        return None;
111	+    };
112	+    if provider != PROVIDER_DATA_KEY {
113	+        return None;
114	+    }
115	+    // The parse error is not logged, because it can hold a value of the data.
116	+    let Ok(parsed) = AnthropicData::deserialize(data) else {
117	+        tracing::debug!(
118	+            target: "paigasus::anthropic::translate",
119	+            "skipping anthropic provider data that does not parse",
120	+        );
121	+        return None;
122	+    };
123	+    if let AnthropicData::Block { index, block } = &parsed {
124	+        if !block.is_valid() {
125	+            tracing::debug!(
126	+                target: "paigasus::anthropic::translate",
127	+                index = *index,
128	+                block_type = block.type_name(),
129	+                "skipping anthropic thinking block that is not valid",
130	+            );
131	+            return None;
132	+        }
133	+    }
134	+    Some((parsed, call_id.as_deref()))
