+        let out = translate_messages(&items);
+        assert_eq!(out.system, Some(Value::String("s1\ns2".to_owned())));
+        assert_eq!(out.messages, json!([utext("q"), utext("r")]));
+        assert!(!out.trailing_message_dropped);
+    }
